import{_ as a,o as i,c as n,a2 as t}from"./chunks/framework.BHPdYWoL.js";const o="/images/GESummaryEarthSpheres.png",r="/images/GESustainabilityIssuesSCurve.webp",s="/images/GESummaryBiosphere.png",b=JSON.parse('{"title":"Gaiaengineering","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),h={name:"index.md"};function d(c,e,p,l,u,g){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="gaiaengineering" tabindex="-1">Gaiaengineering <a class="header-anchor" href="#gaiaengineering" aria-label="Permalink to &quot;Gaiaengineering&quot;">​</a></h1><p><strong>The Planetary Systems Research Hub for Biosphere &amp; Anthroposphere Survival.</strong></p><blockquote><p>&quot;Nature does not treat carbon as toxic waste to be buried underground; Nature uses carbon to build the world.&quot;</p><p>— John Harrison, Founder</p></blockquote><h2 id="the-mission" tabindex="-1">The Mission <a class="header-anchor" href="#the-mission" aria-label="Permalink to &quot;The Mission&quot;">​</a></h2><p>Humanity is facing a compound systemic crisis: a rapidly degrading atmosphere, hydrosphere and biosphere and a decaying Anthrosphere, where real wealth per capita is eroded by institutional bloat, Parkinson&#39;s Laws, and a diminishing Genuine Progress Indicator (GPI).</p><p><img src="'+o+'" alt="The Earth&#39;s interacting spheres"></p><p>This reality is the subject matter of Gaiaengineering.org which John Harrison has repurposed as a knowledge hub focusing on the degrading biosphere and issues in the anthroposphere.</p><h2 id="the-anthroposphere" tabindex="-1">The Anthroposphere <a class="header-anchor" href="#the-anthroposphere" aria-label="Permalink to &quot;The Anthroposphere&quot;">​</a></h2><p>As Natural Wealth depletes, human institutions expand administrative overhead to manage the resulting systemic friction. This expansion of Parkinson&#39;s Laws artificially inflates nominal income (GNI/GDP) while causing genuine progress (GPI) and Real Wealth per capita to collapse together.</p><h2 id="the-science" tabindex="-1">The Science <a class="header-anchor" href="#the-science" aria-label="Permalink to &quot;The Science&quot;">​</a></h2><p>John Harrison who was the author of the TecEco.org web and since 2020 pioneered the foundational science relating to the use of reactive MgO (rMgO) in cements, concretes and other building materials. He also demonstrated that bio mimetic carbon capture was the only viable way to sequester gigatons of CO₂. His Eco-cements emulated nature by using CO2 to build our infrastructure. While modern startups spend billions attempting to reinvent these proven principles, TecEco.org continues as the originator and repository of knowledge on the science. Papers from other authors are welcome and they will not necessarily be rejected because we disagree with them.</p><h2 id="the-knowledge-hub" tabindex="-1">The Knowledge Hub <a class="header-anchor" href="#the-knowledge-hub" aria-label="Permalink to &quot;The Knowledge Hub&quot;">​</a></h2><p>John has extended the boundaries of the original work he did as on the TecEco.org web site to many other issues and repurposed Gaiaengineering.org, as a knowledge hub focusing on the degrading biosphere and productivity issues in the anthrosphere. Problems and concerns addressed on Gaiaengineering.org including the loss of polar ice, methane emissions, rising ocean acidity and many other alarming signals of imminent potential biosphere collapse that most people are unaware of.</p><p><img src="'+r+'" alt="Sustainability issues on the S-curve"></p><p><img src="'+s+'" alt="The biosphere"></p>',15)])])}const f=a(h,[["render",d]]);export{b as __pageData,f as default};
